cards.styles:
:host {
  --bubble-button-box-shadow: none !important;
  --bubble-button-main-background-color: transparent !important;
}

ha-card {
  border-radius: 16px !important;
  border: 1px solid rgba(140,210,230,0.16) !important;
  background: linear-gradient(
    135deg,
    rgba(50,80,95,0.80) 0%,
    rgba(50,62,85,0.55) 100%
  ) !important;
  box-shadow:
    0 6px 18px rgba(0,0,0,0.22),
    inset 0 1px 0 rgba(255,255,255,0.06) !important;
}

.bubble-name-container {
  display: none !important;
}

.bubble-sub-button-container {
  width: 70% !important;
  flex: 1 !important;
  justify-content: space-between !important;
  gap: 10px !important;
  overflow: visible !important;
}

.bubble-sub-button {
  position: relative !important;
  height: 44px !important;
  min-height: 44px !important;
  width: 44px !important;
  min-width: 44px !important;
  flex-shrink: 0 !important;
  box-sizing: border-box !important;
  padding: 0 !important;
  overflow: visible !important;
}

.bubble-sub-button-icon {
  --mdc-icon-size: 25px !important;
  color: inherit !important;
}

/* Presenças: avatares redondos */
.bubble-sub-button-1,
.bubble-sub-button-2 {
  border-radius: 50% !important;
}

.bubble-sub-button-1 {
  color: ${hass.states['device_tracker.pixel_10a']?.state === 'home' ? '#F48FB1' : 'rgba(255,255,255,0.35)'} !important;
  background: ${hass.states['device_tracker.pixel_10a']?.state === 'home' ? 'rgba(244,143,177,0.10)' : 'rgba(255,255,255,0.03)'} !important;
  border: 1px solid ${hass.states['device_tracker.pixel_10a']?.state === 'home' ? 'rgba(244,143,177,0.25)' : 'rgba(255,255,255,0.08)'} !important;
  margin-left: 16px !important;
}

.bubble-sub-button-2 {
  color: ${hass.states['device_tracker.oneplus_12_nunogps']?.state === 'home' ? '#64A0FF' : 'rgba(255,255,255,0.35)'} !important;
  background: ${hass.states['device_tracker.oneplus_12_nunogps']?.state === 'home' ? 'rgba(100,160,255,0.10)' : 'rgba(255,255,255,0.03)'} !important;
  border: 1px solid ${hass.states['device_tracker.oneplus_12_nunogps']?.state === 'home' ? 'rgba(100,160,255,0.25)' : 'rgba(255,255,255,0.08)'} !important;
}

/* Indicador de presença */
.bubble-sub-button-1::after,
.bubble-sub-button-2::after {
  content: "";
  position: absolute;
  bottom: 0;
  right: 0;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  border: 2px solid #233b48;
  pointer-events: none;
}

.bubble-sub-button-1::after {
  background: ${hass.states['device_tracker.mariana_2']?.state === 'home' ? '#72D99B' : '#71808A'};
}

.bubble-sub-button-2::after {
  background: ${hass.states['device_tracker.oneplus_12_nunogps']?.state === 'home' ? '#72D99B' : '#71808A'};
}

/* Cenários alinhados à direita */
.bubble-sub-button-3 {
  margin-left: auto !important;
}

.bubble-sub-button-3,
.bubble-sub-button-4 {
  border-radius: 10px !important;
  background: rgba(100,200,120,0.06) !important;
  border: 1px solid rgba(100,200,120,0.18) !important;
  color: rgba(100,200,120,0.95) !important;
}

/* Separador antes dos cenários */
.bubble-sub-button-3::before {
  content: "";
  position: absolute;
  left: -15px;
  top: 9px;
  height: 24px;
  width: 1px;
  background: rgba(160,200,215,0.20);
  pointer-events: none;
}

:host {
  --bubble-button-box-shadow: none !important;
  --bubble-button-main-background-color: transparent !important;
}
ha-card {
  border-radius: 16px !important;
  border: 1px solid rgba(140,210,230,0.16) !important;
  background: linear-gradient(135deg, rgba(38,72,85,0.75) 0%, rgba(15,32,45,0.90) 100%) !important;
  box-shadow: 0 6px 18px rgba(0,0,0,0.22), inset 0 1px 0 rgba(255,255,255,0.06) !important;
}
.bubble-name {
  font-size: 23px !important;
  font-weight: 500 !important;
  color: rgba(255,255,255,0.8) !important;
}

.bubble-sub-button-3 ha-icon {
  --mdc-icon-size: 35px !important;
  color: ${!['off','unknown','unavailable'].includes(hass.states['climate.quarto_gaming_ac_gaming_room']?.state ?? 'unavailable') ? 'deepskyblue' : 'rgba(255,255,255,0.5)'} !important;
}
.bubble-sub-button-3 {
  background: ${!['off','unknown','unavailable'].includes(hass.states['climate.quarto_gaming_ac_gaming_room']?.state ?? 'unavailable') ? 'rgba(0,191,255,0.08)' : 'transparent'} !important;
  border: 1px solid ${!['off','unknown','unavailable'].includes(hass.states['climate.quarto_gaming_ac_gaming_room']?.state ?? 'unavailable') ? 'rgba(0,191,255,0.3)' : 'rgba(255,255,255,0.07)'} !important;
}

  .bubble-sub-button-2 {
  border-radius: 12px !important;
  min-width: 55px !important;
  min-height: 50px !important;
  background: transparent !important;
}

  .bubble-sub-button-1 {
  border-radius: 12px !important;
  min-width: 55px !important;
  min-height: 50px !important;
  background: transparent !important;
}

.bubble-sub-button-4 ha-icon {
  --mdc-icon-size: 35px !important;
  color: ${hass.states['light.groupoluzgamingroom']?.state === 'on' ? 'rgba(255,165,0,0.9)' : 'rgba(255,255,255,0.5)'} !important;
}
.bubble-sub-button-4 {
  background: ${hass.states['light.groupoluzgamingroom']?.state === 'on' ? 'rgba(255,165,0,0.08)' : 'transparent'} !important;
  border: 1px solid ${hass.states['light.groupoluzgamingroom']?.state === 'on' ? 'rgba(255,165,0,0.3)' : 'rgba(255,255,255,0.07)'} !important;
}

.bubble-sub-button-4 {
  position: relative !important;
  overflow: visible !important;
  min-width: 65px !important;
}
.bubble-sub-button-4::after {
  content: "${(hass.states['light.groupoluzgamingroom']?.attributes.entity_id ?? []).filter(id => hass.states[id]?.state === 'on').length}";
  display: ${(hass.states['light.groupoluzgamingroom']?.attributes.entity_id ?? []).some(id => hass.states[id]?.state === 'on') ? 'flex' : 'none'};
  position: absolute;
  top: -5px;
  right: -5px;
  width: 20px;
  height: 20px;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: #FFA500;
  color: #15252c;
  border: 2px solid #152b35;
  font-size: 11px;
  font-weight: 700;
  line-height: 1;
  pointer-events: none;
}

.bubble-sub-button-container {
  width: 65%;
  justify-content: space-between !important;
  overflow: visible !important;
}
.bubble-sub-button {
  border-radius: 12px !important;
  min-width: 55px !important;
  min-height: 50px !important;
}

/* Aquecimento: destaque quando a divisão pede calor e o sistema está ativo */
@keyframes aqGlow {
  0%, 100% { opacity: 0.75; }
  50% { opacity: 1; }
}
ha-card {
  position: relative !important;
  border-color: ${(hass.states['input_boolean.aq_gaming_pede_calor']?.state === 'on' && hass.states['binary_sensor.aq_sistema_ativo']?.state === 'on') ? 'rgba(255,120,65,0.55)' : 'rgba(140,210,230,0.16)'} !important;
}
ha-card::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  background: radial-gradient(ellipse at 18% 55%, rgba(255,90,40,0.32) 0%, rgba(255,90,40,0.10) 35%, transparent 65%);
  display: ${(hass.states['input_boolean.aq_gaming_pede_calor']?.state === 'on' && hass.states['binary_sensor.aq_sistema_ativo']?.state === 'on') ? 'block' : 'none'};
  animation: aqGlow 2.4s ease-in-out infinite;
}
.bubble-state {
  color: ${(hass.states['input_boolean.aq_gaming_pede_calor']?.state === 'on' && hass.states['binary_sensor.aq_sistema_ativo']?.state === 'on') ? 'rgba(255,140,80,1)' : 'inherit'} !important;
  font-weight: ${(hass.states['input_boolean.aq_gaming_pede_calor']?.state === 'on' && hass.states['binary_sensor.aq_sistema_ativo']?.state === 'on') ? '600' : 'inherit'} !important;
}
.bubble-state::before {
  content: '🔥 ';
  display: ${(hass.states['input_boolean.aq_gaming_pede_calor']?.state === 'on' && hass.states['binary_sensor.aq_sistema_ativo']?.state === 'on') ? 'inline' : 'none'};
