cards.styles:
/* Fundo igual ao Bubble Card */
.navbar-card {
  --navbar-route-icon-size: 20px;

  background: #203843 !important;
  border: 1px solid rgba(140,210,230,0.30) !important;
  border-radius: 16px !important;
  box-shadow:
    0 6px 24px rgba(0,0,0,0.55),
    inset 0 1px 0 rgba(255,255,255,0.04) !important;
  padding: 8px !important;
  gap: 6px !important;
}

/* Botões compactos */
.navbar-card .route .button {
  height: 34px !important;
  min-height: 34px !important;
  width: 54px !important;
  min-width: 0 !important;
  box-sizing: border-box !important;
  border-radius: 6px !important;
  background: rgba(255,255,255,0.06) !important;
  border: 1px solid rgba(255,255,255,0.08) !important;
  box-shadow: none !important;
}

/* Casa */
.navbar-card .route:nth-child(1) .button {
  background: rgba(101,216,222,0.06) !important;
  border-color: rgba(101,216,222,0.15) !important;
}

.navbar-card .route:nth-child(1) .button.active {
  background: rgba(101,216,222,0.18) !important;
  border-color: rgba(101,216,222,0.45) !important;
}

/* Energia */
.navbar-card .route:nth-child(2) .button {
  background: rgba(100,160,255,0.06) !important;
  border-color: rgba(100,160,255,0.15) !important;
}

