custom_fields.header:
[[[
  const boilerOn = states['switch.caldeira_caldeira']?.state === 'on';
  const forced = states['input_boolean.cald_force_override']?.state === 'on';
  const automatic = states['input_boolean.cald_auto_mode']?.state === 'on';

  let label = 'Inativo';
  let color = 'rgba(160,160,170,0.9)';
  let background = 'rgba(100,100,110,0.14)';

  if (boilerOn && forced) {
    label = 'Forçado';
    color = 'rgba(255,205,55,1)';
    background = 'rgba(220,170,0,0.16)';
  } else if (boilerOn) {
    label = 'A aquecer';
    color = 'rgba(255,120,65,1)';
    background = 'rgba(210,80,40,0.17)';
  } else if (automatic) {
    label = 'Em espera';
    color = 'rgba(110,175,225,1)';
    background = 'rgba(70,130,180,0.16)';
  }

  return `
    <div style="display:flex;align-items:center;justify-content:space-between;width:100%;">
      <span style="font-size:12px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:rgba(255,255,255,.44);">
        Caldeira
      </span>
      <span style="font-size:10px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;padding:4px 10px;border-radius:999px;background:${background};color:${color};">
        ${label}
      </span>
    </div>`;
]]]

custom_fields.temperatures:
[[[
  const boilerOn = states['switch.caldeira_caldeira']?.state === 'on';
  const currentRaw = Number(states['sensor.temperatura_media_da_casa']?.state);
  const targetRaw = Number(states['input_number.cald_temp_setpoint']?.state);
  const current = Number.isFinite(currentRaw) ? currentRaw.toFixed(1) : '–';
  const target = Number.isFinite(targetRaw) ? targetRaw.toFixed(1) : '–';
  const fireColor = boilerOn ? 'rgba(255,115,55,1)' : 'rgba(140,150,155,.34)';
  const fireClass = boilerOn ? 'boiler-fire boiler-fire-active' : 'boiler-fire';

  return `
    <style>
      @keyframes boilerPulse {
        0%,100% { transform:scale(1); opacity:.82; }
        50% { transform:scale(1.12); opacity:1; }
      }
      .boiler-fire-active { animation:boilerPulse 1.6s ease-in-out infinite; }
      @media (prefers-reduced-motion: reduce) {
        .boiler-fire-active { animation:none; }
      }
    </style>
    <div style="display:grid;grid-template-columns:1fr 1px 1fr 48px;align-items:center;gap:22px;width:100%;">
      <div style="display:flex;flex-direction:column;align-items:flex-start;gap:5px;">
        <span style="font-size:38px;font-weight:300;line-height:1;color:rgba(255,153,51,.96);">${current}°</span>
        <span style="font-size:11px;color:rgba(255,255,255,.38);">Média da casa</span>
      </div>
      <span style="width:1px;height:52px;background:rgba(255,255,255,.08);"></span>
      <div style="display:flex;flex-direction:column;align-items:center;gap:5px;">
        <span style="font-size:38px;font-weight:300;line-height:1;color:rgba(95,158,160,.96);">${target}°</span>
        <span style="font-size:11px;color:rgba(255,255,255,.38);">Setpoint</span>
      </div>
      <div class="${fireClass}" style="display:grid;place-items:center;color:${fireColor};transform-origin:center;">
        <ha-icon icon="mdi:fire" style="--mdc-icon-size:34px;"></ha-icon>
      </div>
    </div>`;
]]]

