[[[
  const userId = hass.user?.id;

  const utilizadoresConfiguracoes = [
    "693047d606be4b99b3fc2c37f1565a3b",
    "8f9cb09dc643441ebe9d74a2c567fb24",
    "d9c05ffc90d0470a8f4acfabf013f7b4",
    "37856c58270d4e84b363bb5744bad78d"
  ];

  const utilizadoresProgramador = [
    "8f9cb09dc643441ebe9d74a2c567fb24",
    "37856c58270d4e84b363bb5744bad78d",
    "693047d606be4b99b3fc2c37f1565a3b"
  ];

  const opcoes = [
    {
      icon: "mdi:blinds-horizontal-closed",
      label: "Estores",
      url: "/dashboard-smartphone/editcovers"
    },
    {
      icon: "mdi:dishwasher",
      label: "Máquina da Louça",
      url: "/dashboard-smartphone/maquina-louca"
    }
  ];

  if (utilizadoresConfiguracoes.includes(userId)) {
    opcoes.push(
      {
        icon: "mdi:music-box-multiple",
        label: "Música",
        url: "/dashboard-smartphone/musica"
      },
      {
        icon: "line-md:cog",
        label: "Configurações",
        url: "/dashboard-smartphone/configs"
      }
    );
  }

  if (utilizadoresProgramador.includes(userId)) {
    opcoes.push({
      icon: "mdi:menu",
      label: "Programador",
      tap_action: {
        action: "call-service",
        service: "input_boolean.toggle",
        target: {
          entity_id: "input_boolean.kisk_mode"
        }
      }
    });
  }

  return opcoes;
]]]

