routes.popup:
[[[
  const userId = hass.user?.id;

  const utilizadoresConfiguracoes = [
    "693047d606be4b99b3fc2c37f1565a3b",
    "8f9cb09dc643441ebe9d74a2c567fb24",
    "d9c05ffc90d0470a8f4acfabf013f7b4",
    "37856c58270d4e84b363bb5744bad78d"
  ];

  const utilizadoresProgramador = [
    "8f9cb09dc643441ebe9d74a2c567fb24",
    "37856c58270d4e84b363bb5744bad78d",
    "693047d606be4b99b3fc2c37f1565a3b"
  ];

  const opcoes = [
    {
      icon: "mdi:blinds-horizontal-closed",
      label: "Estores",
      url: "/dashboard-smartphone/editcovers"
    },
    {
      icon: "mdi:dishwasher",
      label: "Máquina da Louça",
      url: "/dashboard-smartphone/maquina-louca"
    }
  ];

  if (utilizadoresConfiguracoes.includes(userId)) {
    opcoes.push(
      {
        icon: "mdi:music-box-multiple",
        label: "Música",
        url: "/dashboard-smartphone/musica"
      },
      {
        icon: "line-md:cog",
        label: "Configurações",
        url: "/dashboard-smartphone/configs"
      }
    );
  }

  if (utilizadoresProgramador.includes(userId)) {
    opcoes.push({
      icon: "mdi:menu",
      label: "Programador",
      tap_action: {
        action: "call-service",
        service: "input_boolean.toggle",
        target: {
          entity_id: "input_boolean.kisk_mode"
        }
      }
    });
  }

  return opcoes;
]]]

cards.styles:
/* Fundo igual ao Bubble Card */
.navbar-card {
  --navbar-route-icon-size: 20px;

  background: #203843 !important;
  border: 1px solid rgba(140,210,230,0.30) !important;
  border-radius: 16px !important;
  box-shadow:
    0 6px 24px rgba(0,0,0,0.55),
    inset 0 1px 0 rgba(255,255,255,0.04) !important;
  padding: 8px !important;
  gap: 6px !important;
}

/* Botões compactos */
.navbar-card .route .button {
  height: 34px !important;
  min-height: 34px !important;
  width: 54px !important;
  min-width: 0 !important;
  box-sizing: border-box !important;
  border-radius: 6px !important;
  background: rgba(255,255,255,0.06) !important;
  border: 1px solid rgba(255,255,255,0.08) !important;
  box-shadow: none !important;
}

/* Casa */
.navbar-card .route:nth-child(1) .button {
  background: rgba(101,216,222,0.06) !important;
  border-color: rgba(101,216,222,0.15) !important;
}

.navbar-card .route:nth-child(1) .button.active {
  background: rgba(101,216,222,0.18) !important;
  border-color: rgba(101,216,222,0.45) !important;
}

/* Energia */
.navbar-card .route:nth-child(2) .button {
  background: rgba(100,160,255,0.06) !important;
  border-color: rgba(100,160,255,0.15) !important;
}

.navbar-card .route:nth-child(2) .button.active {
  background: rgba(100,160,255,0.18) !important;
  border-color: rgba(100,160,255,0.45) !important;
}

/* Caldeira: fundo discreto, ícone com cor dinâmica */
.navbar-card .route:nth-child(3) .button {
  background: rgba(255,255,255,0.035) !important;
  border-color: rgba(255,255,255,0.10) !important;
}

.navbar-card .route:nth-child(3) .button.active {
  background: rgba(255,255,255,0.09) !important;
  border-color: rgba(255,255,255,0.30) !important;
}

/* Aspirador */
.navbar-card .route:nth-child(4) .button {
  background: rgba(60,200,180,0.10) !important;
  border-color: rgba(60,200,180,0.20) !important;
}

.navbar-card .route:nth-child(4) .button.active {
  background: rgba(60,200,180,0.20) !important;
  border-color: rgba(60,200,180,0.45) !important;
}

/* Mais */
.navbar-card .route:nth-child(5) .button {
  background: rgba(100,200,120,0.06) !important;
  border-color: rgba(100,200,120,0.15) !important;
}

.navbar-card .route:nth-child(5) .button.active {
  background: rgba(100,200,120,0.18) !important;
  border-color: rgba(100,200,120,0.45) !important;
}

/* Legendas no desktop */
.navbar-card .label {
  color: rgba(255,255,255,0.65) !important;
  font-size: 12px !important;
  font-weight: 500 !important;
}

.navbar-card .label.active {
  color: rgba(255,255,255,0.95) !important;
}

/* Popup com o degradê dos Bubble Cards */
.navbar-popup {
  background: linear-gradient(
    315deg,
    rgba(38,72,85,0.95) 0%,
    rgba(15,32,45,0.98) 100%
  ) !important;
  backdrop-filter: blur(14px) !important;
  -webkit-backdrop-filter: blur(14px) !important;
  border: 1px solid rgba(140,210,230,0.16) !important;
  border-radius: 16px !important;
  box-shadow:
    0 6px 18px rgba(0,0,0,0.22),
    inset 0 1px 0 rgba(255,255,255,0.06) !important;
  padding: 12px !important;
}

.popup-item .button {
  background: rgba(255,255,255,0.06) !important;
  border: 1px solid rgba(140,210,230,0.16) !important;
  border-radius: 10px !important;
  box-shadow: none !important;
}

.popup-item .icon {
  color: #65D8DE !important;
}

.popup-item .label {
  color: rgba(255,255,255,0.90) !important;
  background: transparent !important;
  box-shadow: none !important;
  font-size: 13px !important;
}

