custom_fields.subtitle:
[[[
  const vacuum = states['vacuum.vaccuminator'];
  const battery = states['sensor.vaccuminator_battery_level']?.state;
  const labels = {
    cleaning: 'A limpar',
    paused: 'Em pausa',
    returning: 'A regressar à base',
    docked: 'Na base',
    idle: 'Pronto',
    unavailable: 'Indisponível',
    unknown: 'Desconhecido'
  };
  const status = labels[vacuum?.state] || vacuum?.state || 'Indisponível';
  return battery && !['unknown', 'unavailable'].includes(battery)
    ? `${status} · ${battery}%`
    : status;
]]]

