label.color:
[[[
  const state = entity?.state?.split('.').pop().toLowerCase() || '';
  if (['run','running'].includes(state)) return '#65d8de';
  if (['ready','inactive','finished','completed'].includes(state)) return '#58d6a8';
  if (['pause','paused','delayedstart'].includes(state)) return '#ffb450';
  if (['error','actionrequired'].includes(state)) return '#ff6b75';
  return 'rgba(255,255,255,0.58)';
]]]

